      "id": "cmd-yum",
      "label": "yum",
      "type": "command",
      "exam": "101",
      "tema": "102",
      "subtopic_id": "102.5",
      "title": "Comando: yum",
      "desc": "Instalar, actualizar, desinstalar paquetes y gestionar la caché en Red Hat/CentOS/Fedora",
      "syntax": "sudo dnf install -y nginx; sudo dnf clean all",
      "flags": [
        {
          "flag": "install [-y] <paquete>",
          "desc": "Descarga e instala el paquete y todas sus dependencias necesarias. La opción -y responde 'yes' automáticamente."
        },
        {
          "flag": "update [paquete]",
          "desc": "🎯 Actualiza el paquete indicado o todo el sistema completo si no se especifica nombre."
        },
        {
          "flag": "check-update",
          "desc": "🎯 Clave de Examen: Comprueba si existen actualizaciones disponibles devolviendo código de salida 100 si las hay (ideal para scripts)."
        },
        {
          "flag": "remove <paquete>",
          "desc": "Desinstala el paquete y retira las dependencias no utilizadas que quedaron huérfanas."
        },
        {
          "flag": "reinstall <paquete>",
          "desc": "Vuelve a descargar e instalar la misma versión para restaurar archivos dañados."
        },
        {
          "flag": "clean all",
          "desc": "🎯 Borra todos los paquetes descargados y vacía los índices de metadatos de la caché local (/var/cache/dnf/)."
        },
        {
          "flag": "search <término>",
          "desc": "Busca coincidencias en el nombre, resumen y descripción de todos los paquetes disponibles."
        },
        {
          "flag": "info <paquete>",
          "desc": "Muestra metadatos detallados (versión, licencia, tamaño, resumen) similar a 'rpm -qi' pero sobre repositorios remotos."
        },
        {
          "flag": "provides / whatprovides <archivo>",
          "desc": "🎯 Clave Absoluta de Examen: Localiza qué paquete proporciona un comando, archivo o librería concreta (ej: yum provides */semanage)."
        },
        {
          "flag": "repolist [all|enabled|disabled]",
          "desc": "🎯 Muestra la lista de repositorios configurados y su estado (activos o deshabilitados)."
        },
        {
          "flag": "repoquery -l <paquete>",
          "desc": "Lista todos los ficheros que componen un paquete remoto sin necesidad de descargarlo ni instalarlo."
        }
      ],
      "examples": [
        "sudo dnf install -y nginx; sudo dnf clean all",
        "dnf provides /bin/ls; dnf repolist"
      ],
      "exam_tips": [
        {
          "q_num": 25,
          "exam": "101",
          "stem": "What is true regarding the configuration of yum? (Choose two.)",
          "answer": "The configuration of package repositories can be divided into multiple files. y Repository configurations can include variables such as $basearch or $releasever.",
          "explanation": "Según man 5 yum.conf , yum lee su configuración global de /etc/yum.conf y permite dividir las definiciones de repositorios en múltiples archivos .repo dentro de /etc/yum.repos.d/ . Además, soporta variables dinámicas integradas como $releasever (versión de la distribución) y $basearch (arquitectura ..."
        },
        {
          "q_num": 51,
          "exam": "101",
          "stem": "A yum repository can declare sets of related packages. Which yum command installs all packages belonging to the group admintools?",
          "answer": "yum groupinstall admintools",
          "explanation": "De acuerdo con man 8 yum , el subcomando groupinstall (o group install ) se utiliza para instalar todos los paquetes pertenecientes a un grupo definido en el repositorio."
        },
        {
          "q_num": 52,
          "exam": "101",
          "stem": "What directory contains configuration files for additional yum repositories? (Specify the full path to the directory.)",
          "answer": "/etc/yum.repos.d (también aceptado /etc/yum.repos.d/ )",
          "explanation": "Según man 5 yum.conf , por defecto yum almacena y lee los archivos de configuración de repositorios adicionales ( .repo ) en el directorio /etc/yum.repos.d ."
        }
      ],
      "slide_url": "t102/102-5-gestion-de-paquetes-rpm.html#/7",
      "practice_url": "practicas/p-102-5-paquetes-rpm-yum.html",
      "weight": 2
