      "id": "cmd-svm",
      "label": "svm",
      "type": "command",
      "exam": "101",
      "tema": "102",
      "subtopic_id": "102.6",
      "title": "Comando: svm",
      "desc": "Detectar los flags de virtualización por hardware en procesadores Intel y AMD",
      "syntax": "grep -E --color=auto '(vmx|svm)' /proc/cpuinfo | head -n 1 | cut -d: -f2 | tr ' ' '\\n' | grep -E '(vmx|svm)'",
      "flags": [
        {
          "flag": "vmx",
          "desc": "🎯 Flag de Intel: Virtual Machine eXtensions (tecnología Intel VT-x). Indica que la CPU soporta virtualización de KVM."
        },
        {
          "flag": "svm",
          "desc": "🎯 Flag de AMD: Secure Virtual Machine (tecnología AMD-V). Indica soporte de virtualización KVM en procesadores AMD."
        },
        {
          "flag": "lscpu",
          "desc": "Comando alternativo de alto nivel que muestra la línea 'Virtualization: VT-x' o 'AMD-V'."
        },
        {
          "flag": "lsmod | grep kvm",
          "desc": "Verifica si los módulos del kernel están cargados en memoria (kvm y kvm_intel o kvm_amd)."
        }
      ],
      "examples": [
        "grep -E --color=auto '(vmx|svm)' /proc/cpuinfo | head -n 1 | cut -d: -f2 | tr ' ' '\\n' | grep -E '(vmx|svm)'"
      ],
