      "id": "cmd-virt-install",
      "label": "virt-install",
      "type": "command",
      "exam": "101",
      "tema": "102",
      "subtopic_id": "102.6",
      "title": "Comando: virt-install",
      "desc": "Crear, arrancar y administrar el ciclo de vida de máquinas virtuales",
      "syntax": "virt-install --name debian-vm --memory 2048 --vcpus 2 --disk size=20 --cdrom debian.iso --os-variant debian11 --noautoconsole; virsh list --all",
      "flags": [
        {
          "flag": "--name <nombre>",
          "desc": "Nombre único asignado a la nueva máquina virtual en libvirt."
        },
        {
          "flag": "--memory <MB> / --vcpus <N>",
          "desc": "Asigna la cantidad de memoria RAM (en megabytes) y el número de cores virtuales de CPU."
        },
        {
          "flag": "--disk path=<ruta>,size=<GB>",
          "desc": "Especifica el archivo de disco virtual o crea uno nuevo con el tamaño indicado."
        },
        {
          "flag": "--cdrom <imagen.iso>",
          "desc": "Monta una imagen ISO como unidad óptica de arranque para la instalación."
        },
        {
          "flag": "virsh list [--all]",
          "desc": "🎯 Lista las máquinas virtuales activas (o todas con --all)."
        },
        {
          "flag": "virsh start | shutdown | destroy <vm>",
          "desc": "🎯 start arranca la VM; shutdown envía señal de apagado ACPI limpio; destroy fuerza el apagado inmediato (corte de corriente)."
        }
      ],
      "examples": [
        "virt-install --name debian-vm --memory 2048 --vcpus 2 --disk size=20 --cdrom debian.iso --os-variant debian11 --noautoconsole; virsh list --all"
      ],
      "exam_tips": [],
