      "id": "cmd-ssh-keygen",
      "label": "ssh-keygen",
      "type": "command",
      "exam": "101",
      "tema": "102",
      "subtopic_id": "102.6",
      "title": "Comando: ssh-keygen",
      "desc": "Generar pares de claves pública/privada y desplegarlas en servidores remotos",
      "syntax": "ssh-keygen -t rsa -b 4096 -f ~/.ssh/id_rsa -N ''; ls -l ~/.ssh/",
      "flags": [
        {
          "flag": "ssh-keygen",
          "desc": "Genera el par de claves criptográficas (privada y pública)."
        },
        {
          "flag": "id_rsa (Clave Privada)",
          "desc": "⚠️ ¡Secreta y personal! NUNCA debe salir de tu ordenador local. Permisos estrictos: 0600 (-rw-------)."
        },
        {
          "flag": "id_rsa.pub (Clave Pública)",
          "desc": "Se copia libremente a todos los servidores a los que desees acceder. Permisos: 0644."
        },
        {
          "flag": "ssh-copy-id usuario@host",
          "desc": "🎯 Clave de Examen: Copia tu clave pública e inyecta su contenido en el archivo remoto ~/.ssh/authorized_keys de forma automática."
        },
        {
          "flag": "~/.ssh/authorized_keys",
          "desc": "🎯 Archivo en el servidor donde se almacenan las claves públicas autorizadas. Permisos obligatorios: 0600 (y el directorio ~/.ssh 0700)."
        }
      ],
      "examples": [
        "ssh-keygen -t rsa -b 4096 -f ~/.ssh/id_rsa -N ''; ls -l ~/.ssh/"
      ],
      "exam_tips": [],
      "slide_url": "t102/102-6-linux-como-sistema-virtu.html#/10",
      "practice_url": "practicas/p-102-6-virtualizacion-cloud.html",
      "weight": 2
