      "id": "cmd-type",
      "label": "type",
      "type": "command",
      "exam": "101",
      "tema": "103",
      "subtopic_id": "103.1",
      "title": "Comando: type",
      "desc": "Averiguar la naturaleza exacta de un comando y su ubicación en el sistema",
      "syntax": "type cd; type ls; type -a echo; which ls",
      "flags": [
        {
          "flag": "type <comando>",
          "desc": "🎯 Clave de Examen: Describe si el comando es un 'builtin' (interno de la shell), un 'alias', una 'function' o un 'file' ejecutable en disco."
        },
        {
          "flag": "type -a <comando>",
          "desc": "🎯 Muestra todas las ubicaciones y naturalezas del comando en el orden exacto en que Bash las ejecutaría."
        },
        {
          "flag": "which <comando>",
          "desc": "🎯 Busca en los directorios listados en la variable $PATH y devuelve la ruta absoluta del primer binario ejecutable que coincida."
        },
        {
          "flag": "whereis <comando>",
          "desc": "Localiza el binario, el código fuente y las páginas del manual de un comando en rutas estándar del sistema."
        },
        {
          "flag": "hash [-r]",
          "desc": "Muestra la tabla hash en memoria donde Bash almacena las rutas de los programas ejecutados recientemente (-r limpia la tabla)."
        },
        {
          "flag": "which -a <comando>",
          "desc": "Muestra todas las coincidencias en $PATH, no solo la primera."
        },
        {
          "flag": "whereis -b <comando>",
          "desc": "🎯 Clave de Examen: Muestra ÚNICAMENTE las rutas de los archivos binarios ejecutables (Binary)."
        },
        {
          "flag": "whereis -m <comando>",
          "desc": "🎯 Clave de Examen: Muestra ÚNICAMENTE las rutas de las páginas del manual man (Manuals)."
        },
        {
          "flag": "whereis -s <comando>",
          "desc": "Muestra únicamente el código fuente del comando si está instalado (Sources)."
        },
        {
          "flag": "type -t <comando>",
          "desc": "🎯 Clave de Examen: Devuelve una única palabra clasificatoria: 'builtin' (comando interno de la shell), 'alias' (atajo personalizado), 'file' (ejecutable en disco) o 'function'."
        },
        {
          "flag": "¿Por qué which falla?",
          "desc": "🎯 'which' solo sabe examinar carpetas de disco en $PATH. Comandos como 'cd', 'export', 'unset', 'exit' o 'history' residen en la memoria dentro del binario de Bash y no son archivos en disco."
        }
      ],
      "examples": [
        "type cd; type ls; type -a echo; which ls",
        "which passwd; whereis passwd",
        "type cd; type -t cd; type -t ls; type -t grep"
      ],
      "exam_tips": [
        {
          "q_num": 1,
          "exam": "101",
          "stem": "Which type of file system is created by mkfs when it is executed with the block device name only and without any additional parameters?",
          "answer": "ext2",
          "explanation": "Según la documentación man 8 mkfs, cuando mkfs se invoca sin especificar el tipo de sistema de archivos mediante el parámetro -t , utiliza por defecto ext2 por razones históricas de compatibilidad con versiones anteriores de util-linux ."
        },
        {
          "q_num": 73,
          "exam": "101",
          "stem": "Which of the following commands show how the shell handles a specific command?",
          "answer": "type",
          "explanation": "El comando interno de Bash type indica cómo interpretaría la shell un nombre de comando si se ejecutara: si es un alias, una palabra reservada ( keyword ), una función, un comando interno ( builtin ) o un archivo ejecutable en disco."
        },
        {
          "q_num": 113,
          "exam": "101",
          "stem": "Which of the following tools can show the complete path of an executable file that the current shell would execute when starting a command without specifying it...",
          "answer": "which y type",
          "explanation": "Tanto el comando externo which como el comando interno de la shell type buscan en la variable $PATH y muestran la ruta completa al archivo ejecutable que se invocaría."
        }
      ],
