      "id": "cmd-tee",
      "label": "tee",
      "type": "command",
      "exam": "101",
      "tema": "103",
      "subtopic_id": "103.4",
      "title": "Comando: tee",
      "desc": "Duplicar el flujo de datos: envía una copia a la salida estándar (pantalla) y otra copia a uno o varios archivos",
      "syntax": "echo 'Instalacion completada' | tee -a /tmp/instalacion.log",
      "flags": [
        {
          "flag": "tee <archivo>",
          "desc": "🎯 Escribe los datos en el archivo indicado (sobrescribiéndolo) y simultáneamente los reproduce en stdout."
        },
        {
          "flag": "tee -a, --append",
          "desc": "🎯 Clave de Examen: Modo concatenación: añade los datos al final del archivo sin borrar lo existente."
        },
        {
          "flag": "sudo tee <archivo_root>",
          "desc": "🎯 Truco Clásico de Sysadmin: Permite escribir en archivos protegidos de root dentro de una tubería: 'echo \"1\" | sudo tee /proc/sys/net/ipv4/ip_forward'."
        }
      ],
      "examples": [
        "echo 'Instalacion completada' | tee -a /tmp/instalacion.log"
      ],
      "exam_tips": [
        {
          "q_num": 37,
          "exam": "101",
          "stem": "Which of the following commands displays the output of the foo command on the screen and also writes it to a file called /tmp/foodata?",
          "answer": "foo | tee /tmp/foodata",
          "explanation": "El comando tee ( man 1 tee ) lee de la entrada estándar y escribe simultáneamente tanto en la salida estándar (pantalla) como en uno o más archivos especificados."
        }
      ],
      "slide_url": "t103/103-4-uso-de-secuencias-de-tex.html#/8",
