      "title": "Comando: jobs",
      "desc": "Lanzar tareas en segundo plano, suspenderlas temporalmente y alternar su ejecución",
      "syntax": "sleep 1000 &; jobs -l; fg %1",
      "flags": [
        {
          "flag": "comando &",
          "desc": "🎯 Clave de Examen: El signo '&' al final lanza la orden directamente en segundo plano (background), liberando el prompt al instante."
        },
        {
          "flag": "jobs [-l]",
          "desc": "🎯 Lista los trabajos activos de la shell actual. '-l' añade el PID de cada proceso."
        },
        {
          "flag": "Ctrl + Z",
          "desc": "🎯 Clave de Examen: Envía la señal SIGTSTP (20/19/18) que SUSPENDE (detiene) de forma inmediata el proceso que corre en primer plano."
        },
        {
          "flag": "bg [%n]",
          "desc": "🎯 Reanuda la ejecución del trabajo detenido (%n o el más reciente) en segundo plano (background)."
        },
        {
          "flag": "fg [%n]",
          "desc": "🎯 Trae el trabajo detenido o en segundo plano (%n) a primer plano (foreground), volviendo a bloquear la consola."
        }
      ],
      "examples": [
        "sleep 1000 &; jobs -l; fg %1"
      ],
      "exam_tips": [
        {
          "q_num": 115,
          "exam": "101",
          "stem": "Which command displays a list of all background tasks running in the current shell? (Specify ONLY the command without any path or parameters.)",
          "answer": "jobs",
          "explanation": "El comando interno de la shell jobs ( help jobs ) lista todas las tareas iniciadas desde la sesión actual de la shell que se encuentran en segundo plano o suspendidas."
        }
      ],
