      "id": "cmd-nohup",
      "label": "nohup",
      "type": "command",
      "exam": "101",
      "tema": "103",
      "subtopic_id": "103.5",
      "title": "Comando: nohup",
      "desc": "Hacer un proceso inmune a la desconexión SIGHUP y monitorizar salidas periódicas",
      "syntax": "nohup ./backup_largo.sh &; head -n 2 nohup.out",
      "flags": [
        {
          "flag": "nohup <comando> &",
          "desc": "🎯 Clave de Examen: No Hangup: ejecuta el comando interceptando la señal SIGHUP. Si cierras la terminal o cae la red, el proceso sigue vivo en el servidor."
        },
        {
          "flag": "nohup.out",
          "desc": "🎯 Clave de Examen: Archivo automático en el directorio actual (o en $HOME) donde nohup redirige la salida del proceso si no se especificó redirección manual."
        },
        {
          "flag": "disown [-h] [%n]",
          "desc": "Desvincula un trabajo en segundo plano de la tabla de la shell para que no reciba SIGHUP al cerrar sesión."
        },
        {
          "flag": "watch -n <seg> <cmd>",
          "desc": "🎯 Ejecuta el comando repetidamente cada N segundos (por defecto 2s) mostrando los cambios en pantalla a pantalla completa (ej: 'watch -n 1 free -m')."
        }
      ],
      "examples": [
        "nohup ./backup_largo.sh &; head -n 2 nohup.out"
      ],
      "exam_tips": [
        {
          "q_num": 108,
          "exam": "101",
          "stem": "The command dbmaint & was used to run dbmaint in the background. However, dbmaint is terminated after logging o ut of the system. Which alternative dbmaint invo...",
          "answer": "nohup dbmaint &",
          "explanation": "Al cerrar la sesión, la shell envía la señal SIGHUP ( hangup ) a sus procesos hijos, terminándolos. El comando nohup ( man 1 nohup ) ejecuta el comando haciendo que ignore la señal SIGHUP , permitiéndole continuar en segundo plano tras cerrar la sesión."
        }
      ],
      "slide_url": "t103/103-5-crear-supervisar-y-matar.html#/4",
      "practice_url": "practicas/p-103-5-procesos-senales.html",
