      "id": "cmd-fdisk",
      "label": "fdisk",
      "type": "command",
      "exam": "101",
      "tema": "104",
      "subtopic_id": "104.1",
      "title": "Comando: fdisk",
      "desc": "Crear, modificar, listar o eliminar particiones MBR de forma interactiva",
      "syntax": "sudo fdisk -l /dev/sdb",
      "flags": [
        {
          "flag": "fdisk -l [disco]",
          "desc": "🎯 Clave de Examen: Lista todas las particiones existentes y la tabla del disco sin entrar en modo interactivo."
        },
        {
          "flag": "Subcomando 'm'",
          "desc": "Muestra el menú de ayuda con todos los comandos interactivos disponibles."
        },
        {
          "flag": "Subcomando 'p'",
          "desc": "🎯 Print: imprime en pantalla la tabla de particiones actual del disco abierto."
        },
        {
          "flag": "Subcomando 'n'",
          "desc": "🎯 New: crea una nueva partición (solicita si es primaria o extendida, sector inicial y tamaño)."
        },
        {
          "flag": "Subcomando 'd'",
          "desc": "🎯 Delete: elimina una partición existente según su número."
        },
        {
          "flag": "Subcomando 't'",
          "desc": "🎯 Type: cambia el código hexadecimal de tipo de partición (ej: 83 para Linux, 82 para Swap)."
        },
        {
          "flag": "Subcomando 'w'",
          "desc": "🎯 Clave de Examen: Write: escribe y guarda los cambios en el disco físico y sale. ⚠️ Hasta pulsar 'w', nada se ha tocado en disco."
        },
        {
          "flag": "Subcomando 'q'",
          "desc": "Quit: sale inmediatamente de fdisk descartando todos los cambios sin escribir nada."
        }
      ],
      "examples": [
        "sudo fdisk -l /dev/sdb"
      ],
      "exam_tips": [
        {
          "q_num": 24,
          "exam": "101",
          "stem": "Which of the following partition types is used for Linux swap spaces when partitioning hard disk drives?",
          "answer": "82",
          "explanation": "En las tablas de particiones MBR ( fdisk ), los identificadores hexadecimales estándar de Linux son: 82 para Linux swap , 83 para sistemas de archivos nativos de Linux, 8e para Linux LVM y fd para Linux RAID autodetect ( 7 es HPFS/NTFS/exFAT)."
        }
      ],
      "slide_url": "t104/104-1-creacion-de-particiones.html#/4",
      "practice_url": "practicas/p-104-1-crear-particiones-archivos.html",
      "weight": 2
