      "id": "cmd-df",
      "label": "df",
      "type": "command",
      "exam": "101",
      "tema": "104",
      "subtopic_id": "104.2",
      "title": "Comando: df",
      "desc": "Disk Free: reportar el uso del espacio de almacenamiento y consumo de inodos de los sistemas montados",
      "syntax": "df -hT /; echo '---'; df -i /",
      "flags": [
        {
          "flag": "df -h, --human-readable",
          "desc": "🎯 Clave de Examen: Muestra tamaños en potencias de 1024 con sufijos legibles (K, M, G, T)."
        },
        {
          "flag": "df -T, --print-type",
          "desc": "🎯 Clave de Examen: Añade una columna mostrando el TIPO de sistema de archivos (ext4, xfs, btrfs, vfat)."
        },
        {
          "flag": "df -i, --inodes",
          "desc": "🎯 Clave Absoluta de Examen: Muestra la información de INODOS (usados, libres y porcentaje) en lugar de bloques de disco."
        },
        {
          "flag": "df -t <tipo>",
          "desc": "🎯 Filtra la salida para mostrar ÚNICAMENTE los sistemas de archivos del tipo especificado (ej: 'df -t ext4')."
        },
        {
          "flag": "df -x <tipo>",
          "desc": "Excluye de la salida los sistemas de archivos del tipo indicado (ej: 'df -x tmpfs')."
        }
      ],
      "examples": [
        "df -hT /; echo '---'; df -i /"
      ],
      "exam_tips": [],
