      "id": "cmd-du",
      "label": "du",
      "type": "command",
      "exam": "101",
      "tema": "104",
      "subtopic_id": "104.2",
      "title": "Comando: du",
      "desc": "Disk Usage: estimar el espacio real en disco ocupado por archivos y directorios",
      "syntax": "sudo du -sh /var/* 2>/dev/null | sort -h | tail -n 3",
      "flags": [
        {
          "flag": "du -h, --human-readable",
          "desc": "Muestra los tamaños en formato legible para humanos (K, M, G)."
        },
        {
          "flag": "du -s, --summarize",
          "desc": "🎯 Clave de Examen: Muestra ÚNICAMENTE el total acumulado del argumento, sin desglosar subdirectorios."
        },
        {
          "flag": "du -sh <directorio>",
          "desc": "🎯 El combo estrella: resumen en formato humano (ej: 'du -sh /home' devuelve '45G /home')."
        },
        {
          "flag": "du -a, --all",
          "desc": "Muestra el tamaño de absolutamente todos los archivos individuales, no solo de los directorios."
        },
        {
          "flag": "-d <N>, --max-depth=<N>",
          "desc": "🎯 Clave de Examen: Limita la profundidad de exploración a N niveles de carpetas (ej: 'du -h -d 1 /var')."
        },
        {
          "flag": "du -c, --total",
          "desc": "Añade una línea final con la suma total (Grand Total) de todos los elementos analizados."
        }
      ],
      "examples": [
        "sudo du -sh /var/* 2>/dev/null | sort -h | tail -n 3"
      ],
      "exam_tips": [],
      "slide_url": "t104/104-2-mantener-la-integridad-d.html#/4",
      "practice_url": "practicas/p-104-2-integridad-sistemas-archivos.html",
