      "id": "cmd-xfs_repair",
      "label": "xfs_repair",
      "type": "command",
      "exam": "101",
      "tema": "104",
      "subtopic_id": "104.2",
      "title": "Comando: xfs_repair",
      "desc": "Verificar, reparar y desfragmentar sistemas de archivos XFS",
      "syntax": "sudo umount /dev/sdb2; sudo xfs_repair /dev/sdb2",
      "flags": [
        {
          "flag": "xfs_repair <partición>",
          "desc": "🎯 Clave Absoluta de Examen: Herramienta oficial para reparar XFS. ⚠️ ¡Debe ejecutarse SIEMPRE con el sistema de archivos DESMONTADO! No se puede ejecutar sobre sistemas montados."
        },
        {
          "flag": "xfs_repair -n",
          "desc": "🎯 Modo No Modify: solo inspecciona e informa de los fallos encontrados SIN aplicar ninguna modificación en el disco (sustituye a la obsoleta herramienta xfs_check)."
        },
        {
          "flag": "xfs_repair -L",
          "desc": "⚠️ ¡Opción de Último Recurso! Limpia (Zero) el log del journal si está corrupto para permitir arrancar, a riesgo de perder los últimos cambios pendientes."
        },
        {
          "flag": "xfs_fsr [disp]",
          "desc": "🎯 XFS File System Reorganizer: desfragmentador en línea para XFS (se ejecuta con el sistema montado para reordenar bloques contiguos)."
        }
      ],
      "examples": [
        "sudo umount /dev/sdb2; sudo xfs_repair /dev/sdb2"
      ],
