      "id": "cmd-mount",
      "label": "mount",
      "type": "command",
      "exam": "101",
      "tema": "104",
      "subtopic_id": "104.3",
      "title": "Comando: mount",
      "desc": "Acoplar un sistema de archivos al árbol de directorios del sistema operativo",
      "syntax": "sudo mount -t ext4 -o ro,noatime /dev/sdb1 /mnt/backup; mount | grep sdb1",
      "flags": [
        {
          "flag": "mount (sin argumentos)",
          "desc": "🎯 Clave de Examen: Muestra la lista de TODOS los sistemas de archivos montados actualmente en el sistema con sus opciones activas."
        },
        {
          "flag": "mount <disp> <directorio>",
          "desc": "Sintaxis estándar manual (ej: 'sudo mount /dev/sdb1 /mnt')."
        },
        {
          "flag": "-t <tipo>",
          "desc": "Especifica explícitamente el tipo de sistema de archivos (ext4, xfs, vfat, iso9660, nfs). Si se omite, mount lo detecta automáticamente."
        },
        {
          "flag": "-o <opciones_separadas_por_coma>",
          "desc": "🎯 Clave de Examen: Pasa modificadores de montaje específicos (ej: '-o ro,noexec,nosuid')."
        },
        {
          "flag": "mount -a",
          "desc": "🎯 Clave Absoluta de Examen: Monta TODOS los sistemas de archivos listados en /etc/fstab que no tengan la opción 'noauto'."
        },
        {
          "flag": "mount --bind <dir1> <dir2> (o -B)",
          "desc": "🎯 Clave de Examen: Montaje enlazado (Bind Mount): proyecta el contenido de una carpeta existente en un segundo directorio del sistema (ambas rutas muestran los mismos archivos). Muy usado en jaulas chroot y contenedores."
        },
        {
          "flag": "mount -o loop <archivo.iso> <dir>",
          "desc": "🎯 Clave de Examen: Montaje en bucle (Loop Device): asocia un archivo regular que contiene un sistema de archivos (como una ISO o imagen de disco) a un dispositivo virtual '/dev/loop*' para poder leerlo como si fuera un CD físico."
        },
        {
          "flag": "losetup -a",
          "desc": "Muestra todos los dispositivos loop virtuales activos y los archivos de imagen a los que están asociados."
        },
        {
          "flag": "mount -o remount,ro /",
          "desc": "🎯 Caso de Rescate Clásico: Pasa la partición raíz (/) a modo de solo lectura para evitar escrituras en situaciones de emergencia o antes de apagar."
        },
        {
          "flag": "mount -o remount,rw /",
          "desc": "🎯 Si el sistema arranca en modo de rescate monousuario con la raíz en solo lectura, este comando la pasa a lectura/escritura para poder editar archivos de configuración rotos y reparar el arranque."
        },
        {
          "flag": "mount -o remount,noexec /tmp",
          "desc": "Añade directivas de endurecimiento de seguridad sobre la marcha sin reiniciar el servidor."
        }
      ],
      "examples": [
        "sudo mount -t ext4 -o ro,noatime /dev/sdb1 /mnt/backup; mount | grep sdb1",
        "sudo mount --bind /var/www /home/alumno/web; sudo mount -o loop debian.iso /mnt/iso",
        "sudo mount -o remount,ro /mnt/backup; mount | grep /mnt/backup"
      ],
      "exam_tips": [
        {
          "q_num": 4,
          "exam": "101",
          "stem": "Which of the following is true when a file system, which is neither listed in /etc/fstab nor known to system, is mounted manually?",
          "answer": "systemd automatically generates a mount unit and monitors the mount point without changing it.",
          "explanation": "Según man 5 systemd.mount , systemd monitoriza /proc/self/mountinfo de forma continua. Cuando un sistema de archivos se monta manualmente con el comando mount , systemd genera dinámicamente en tiempo de ejecución una unidad .mount asociada y supervisa el punto de montaje sin alterar su estado."
        },
        {
          "q_num": 6,
          "exam": "101",
          "stem": "What does the command mount --bind do?",
          "answer": "It makes the contents of one directory available in another directory.",
          "explanation": "Según man 8 mount , la opción --bind (o -B ) vuelve a montar parte de la jerarquía de archivos existente en otro punto del sistema de archivos, haciendo que el contenido de un directorio sea accesible de forma simultánea desde ambos lugares."
        },
        {
          "q_num": 7,
          "exam": "101",
          "stem": "In order to display all currently mounted filesystems, which of the following commands could be used? (Choose two.)",
          "answer": "cat /proc/self/mounts y mount",
          "explanation": "Ejecutar mount sin argumentos lista todos los sistemas de archivos montados actualmente. Del mismo modo, el archivo virtual /proc/self/mounts (al que enlaza /proc/mounts ) expone directamente desde el kernel todos los sistemas montados en el espacio de nombres actual. ( /proc/filesystems solo muestr..."
        }
      ],
      "slide_url": "t104/104-3-controlar-el-montaje-y-d.html#/3",
      "practice_url": "practicas/p-104-3-montaje-sistemas-archivos.html",
      "weight": 2
