      "id": "cmd-umount",
      "label": "umount",
      "type": "command",
      "exam": "101",
      "tema": "104",
      "subtopic_id": "104.3",
      "title": "Comando: umount",
      "desc": "Desacoplar sistemas de archivos de forma limpia y localizar procesos que bloquean el desmontaje",
      "syntax": "sudo umount /mnt/backup; fuser -vm /mnt/backup",
      "flags": [
        {
          "flag": "umount <disp o dir>",
          "desc": "🎯 Clave de Examen: Se puede desmontar indicando la ruta del dispositivo ('/dev/sdb1') O la ruta del directorio ('/mnt/backup'). Ambos son válidos."
        },
        {
          "flag": "Causa de 'target is busy'",
          "desc": "🎯 Ocurre si un usuario tiene su terminal abierta dentro de esa carpeta (como en la terminal arriba: ACCESS 'c' = current directory) o un programa tiene un archivo abierto en ella."
        },
        {
          "flag": "fuser -vm <directorio>",
          "desc": "🎯 Muestra qué usuarios y PIDs están accediendo al punto de montaje."
        },
        {
          "flag": "fuser -km <directorio>",
          "desc": "🎯 Mata automáticamente con señal SIGKILL todos los procesos que estén reteniendo el punto de montaje."
        },
        {
          "flag": "lsof +D <directorio>",
          "desc": "Lista todos los archivos abiertos dentro de ese directorio y los comandos responsables."
        },
        {
          "flag": "umount -l, --lazy",
          "desc": "🎯 Desmontaje perezoso (Lazy): desvincula el sistema de archivos del árbol de inmediato y limpia referencias cuando los procesos terminen."
        }
      ],
      "examples": [
        "sudo umount /mnt/backup; fuser -vm /mnt/backup"
      ],
      "exam_tips": [],
      "slide_url": "t104/104-3-controlar-el-montaje-y-d.html#/5",
      "practice_url": "practicas/p-104-3-montaje-sistemas-archivos.html",
